import type {DaySummary,MetricAggregate,PeriodSummary} from '../../src/api/contracts'
import {shiftCalendarDate} from '../../src/domain/dates'
export function metric(overrides:Partial<MetricAggregate>={}):MetricAggregate{return {knownSum:null,recordCount:0,knownValueCount:0,missingValueCount:0,legacyValueCount:0,hasData:false,partial:false,...overrides}}
export function daySummary(date:string):DaySummary{return {day:{recordDate:date,intake:metric(),protein:metric(),fat:metric(),carbs:metric(),expenditure:metric(),activityMinutes:null,foodCount:0,exerciseCount:0,foodEntryCount:0,exerciseEntryCount:0},goalComparison:null,facts:[{code:'COVERAGE',text:'No confirmed records in this date range.',values:{}}]}}
export function periodSummary(from:string,to:string):PeriodSummary{const days=[];for(let date=from;date<=to;date=shiftCalendarDate(date,1))days.push(daySummary(date).day);return {rangeStart:from,rangeEnd:to,calendarDayCount:days.length,days,totals:{intake:metric(),protein:metric(),fat:metric(),carbs:metric(),expenditure:metric(),activityMinutes:null,foodCount:0,exerciseCount:0,foodEntryCount:0,exerciseEntryCount:0},averages:{intake:{value:null,knownDayCount:0},protein:{value:null,knownDayCount:0},fat:{value:null,knownDayCount:0},carbs:{value:null,knownDayCount:0},expenditure:{value:null,knownDayCount:0},activityMinutes:{value:null,knownDayCount:0}},goalComparison:null,facts:[]}}
